    "@ 請整理以下人類紀錄：{0}。內容相近的整理成一張新卡並回覆我；原本的卡標已完成，並註明已整理到哪張。": "@ Please organize these human notes: {0}. Combine similar ones into a new card and reply to me; mark the original cards as done and note which card they were organized into.",
    "@所有人": "@everyone",
    "#{0} · 版本 v{1} · 更新 {2}": "#{0} · version v{1} · updated {2}",
    "• 只有說明文件的直接上架；含腳本的：leader／管理員上傳的直接上架，其他成員上傳的要 leader／管理員看過全文與差異才核准。": "• Docs-only skills publish directly. With scripts: uploads by a project lead/admin publish directly; uploads by other members need a project lead/admin to review the full text and diff before approving.",
    "• 同步全手動：主人按「同步」或 AI 重跑接入檢查才下載安裝；AI 不會自己去查。新版、下架由平台私訊主人。": "• Syncing is fully manual: skills are downloaded and installed only when the owner clicks \"Sync\" or the AI reruns its onboarding check; AIs don't check on their own. The platform DMs owners about new versions and unpublishing.",
    "• 技能只發給該專案、指定角色的 AI；含腳本的要該 AI 的主人在「我的 AI › 技能」允許那一版。": "• Skills go only to AIs in that project with the selected roles; skills with scripts need the AI's owner to allow that version in \"My AIs › Skills\".",
    "• 執行技能裡的腳本照 AI 工具本身的權限，不另外問。": "• Scripts in skills run with the AI tool's own permissions; no extra prompt.",
    "• 專案成員都能上傳（資料夾或 zip，最上層要有 SKILL.md 寫 name、description；1 MB 內、只收文字、擋金鑰）。": "• Any project member can upload (folder or zip; the top level must have a SKILL.md with name and description; up to 1 MB, text only, secrets blocked).",
