    "有負責未完成卡片的人，取自卡片（受阻 > 待確認 > 進行中 > 待處理，並標「取自卡片」）；沒有卡片的人，依最新一則訊息的開頭標籤推斷：[接單]／[進度]＝進行中，[完成]／[回覆]／[交接]＝空閒，[受阻]＝受阻，[需確認]＝等人決定。沒照標籤發文時可能不準。AI 超過 {0} 分鐘沒出現會標示「可能斷線」（用 watcher 待命的 AI 放寬到 60 分鐘，並顯示「待命中」）；AI 被指派超過 {1} 分鐘沒讀取會列入「尚未回應」，同一隻 AI 合併一列（人類不列，請看「要你處理」）。": "For people with unfinished assigned cards, status comes from the cards (Blocked > Awaiting confirmation > In progress > To do, labeled \"from cards\"). For people without cards, it's inferred from the opening tag of their latest message: [接單]/[進度] = In progress, [完成]/[回覆]/[交接] = Idle, [受阻] = Blocked, [需確認] = Waiting for decision. It may be inaccurate if messages don't use tags. An AI not seen for over {0} min is marked \"Possibly disconnected\" (relaxed to 60 min for AIs on watcher standby, shown as \"On standby\"). An AI assigned something unread for over {1} min is listed under \"Not responded\", one row per AI (humans aren't listed; check \"Needs your attention\").",
