    "你是「{0}」，{1} 在 Aigile 協作群組的 AI（{2}）。以下是 {3} 交代的接入步驟： {4}1. 在終端機執行下載（一定要執行，會覆蓋舊檔；「只能下載一次」說的是這個連結，不是叫你沿用資料夾裡已經有的檔案。15 分鐘內有效；Windows PowerShell 請把 curl 換成 curl.exe）： curl -s --create-dirs -o {5}/setup.md \"{6}\" 2. 讀 {7}/setup.md：開頭寫的身分必須是「{8}」，不是就停下來告訴 {9}（讀到別的 AI 的檔）。是就照裡面的步驟接入。 3. 接好後 Token 存在 {10}/.token，然後刪掉 {11}/setup.md（裡面有 Token）。這個檔不要進 git、不要貼到群組。 {12} 檔案內容寫「已失效」，就請 {13} 在網頁「我的 AI」重按「複製接入文字」。這段文字與連結都不要貼到群組。": "You are \"{0}\", {1}'s AI in the Aigile collaboration group ({2}). Here are the onboarding steps from {3}: {4}1. Run the download in a terminal (you must run it; it overwrites the old file. \"One download only\" refers to this link; it does not mean reusing a file already in the folder. Valid for 15 minutes; in Windows PowerShell replace curl with curl.exe): curl -s --create-dirs -o {5}/setup.md \"{6}\" 2. Read {7}/setup.md: the identity at the top must be \"{8}\". If not, stop and tell {9} (you got another AI's file). If it is, follow its steps to onboard. 3. Once onboarded, the token is stored in {10}/.token; then delete {11}/setup.md (it contains the token). Never put this file in git or paste it in the group. {12} If the file says \"expired\", ask {13} to click \"Copy onboarding text\" again under My AIs on the web page. Never paste this text or the link in the group.",
    "0. {0}預設沙盒不能連網。~/.codex/config.toml 要有這兩行（改完重開 Codex，不用開完全權限）： sandbox_mode = \"workspace-write\" [sandbox_workspace_write] 底下 network_access = true （或啟動時加 --sandbox workspace-write -c 'sandbox_workspace_write.network_access=true'）": "0. {0}the default sandbox has no network access. ~/.codex/config.toml needs these two lines (restart Codex after editing; full access is not needed): sandbox_mode = \"workspace-write\" and, under [sandbox_workspace_write], network_access = true (or start with --sandbox workspace-write -c 'sandbox_workspace_write.network_access=true') ",
    "如果你是 Codex：": "If you are Codex: ",
    "下載失敗時：看到 127.0.0.1:9、curl 錯誤 7、連線被拒（Connection refused），就是 Codex 沒開網路，不是代理或公司網路問題。請停下來，把第 0 步原文告訴 {0}：「請在 ~/.codex/config.toml 開 network_access 後重開 Codex」，不要說成代理問題、不要換別的寫法重試。開了網路仍連不到，才告訴 {1} 改用「複製完整版」。": "If the download fails: 127.0.0.1:9, curl error 7, or Connection refused means Codex has no network access; it is not a proxy or corporate network problem. Stop and tell {0} step 0 verbatim: \"Please enable network_access in ~/.codex/config.toml and restart Codex\". Don't call it a proxy problem and don't retry another way. Only if the network is enabled and it still can't connect, tell {1} to use \"Copy full version\" instead.",
    "下載失敗時：把錯誤原文告訴 {0}，不要換別的寫法重試；連不到網址就請他確認你這台電腦開得了這個網站。": "If the download fails: tell {0} the exact error and don't retry another way; if the address can't be reached, ask them to check that this computer can open the site.",
    "複製連結": "Copy link",
    "已建立「{0}」。請選擇你使用的 AI 工具。": "Created \"{0}\". Select the AI tool you use.",
    "將一行啟動貼到這隻 AI 的工作資料夾的終端機。需要它工作時開啟 Copilot CLI。": "Paste the one-line command into a terminal in this AI's working folder. Open Copilot CLI when you want it to work.",
    "將一行啟動貼到這隻 AI 的工作資料夾的終端機。保持 Antigravity CLI 視窗開啟即可接收工作。": "Paste the one-line command into a terminal in this AI's working folder. Keep the Antigravity CLI window open to receive work.",
    "將一行啟動貼到這隻 AI 的工作資料夾的終端機。執行即同意自動待命，重開機可以貼同一行接回。": "Paste the one-line command into a terminal in this AI's working folder. Running it enables automatic standby. Use the same command to reconnect after a reboot.",
    "將接入文字貼到這隻 AI 的對話。": "Paste the onboarding text into this AI's chat.",
    "接入連結 15 分鐘內有效，只能使用一次。過期可到「我的 AI」重新複製。": "The onboarding link is valid for 15 minutes and can be used once. If the link expires, get a fresh copy in My AIs.",
    "指令和連結請勿貼到群組。": "Keep the command and link out of group chat.",
