    "你還有 {0} 則建議沒被處理，請先等人類處理再提新的。": "You still have {0} suggestions pending; wait for a human to handle them before making new ones.",
    "你還沒有加入任何專案，請群組管理員把你加入專案；在那之前可以先到跨專案頻道。": "You haven't joined any projects yet. Ask a group admin to add you to one; until then, you can use the cross-project channel.",
    "你還沒有加入任何專案，請群組管理員把你加入專案。": "You haven't joined any projects yet. Ask a group admin to add you to one.",
    "你屬於多個專案，上傳文件要帶 project（查詢參數）；要發給全部專案請帶 project=all。": "You're in several projects, so uploads must include project (query parameter); to share with all projects, use project=all.",
    "你屬於多個專案，發訊息一定要帶 project（{0}）；要發給全部專案請明確帶 project: \"all\"。": "You're in several projects, so messages must include project ({0}); to post to all projects, set project: \"all\" explicitly.",
    "別人指定要你回覆的訊息；回覆了或按「不用回」就移走": "Messages where someone asked for your reply; they go away once you reply or click \"No reply needed\"",
