    "忘記密碼要請有主機權限的人用救援指令（npm run admin-rescue）。": "If you forget your password, ask someone with server access to run the rescue command (npm run admin-rescue).",
    "忘記密碼請管理員（{0}）在「成員管理」按「重設登入」。": "If you forget your password, ask an admin ({0}) to click \"Reset sign-in\" in \"Member management\".",
    "忘記密碼請管理員（{0}）在「成員與權限」按「重設登入」。": "If you forget your password, ask an admin ({0}) to click \"Reset sign-in\" in \"Members & permissions\".",
    "用一台已登入的裝置（{0}）重設了你的密碼，沒有填目前密碼 · {1}。其他裝置都已登出。": "Your password was reset from a signed-in device ({0}) without entering the current password · {1}. All other devices were signed out.",
    "不明裝置": "unknown device",
    "不是你？請管理員在「成員管理」按「重設登入」，再檢查「我的裝置」。": "Not you? Ask an admin to click \"Reset sign-in\" in \"Member management\", then check \"My devices\".",
    "忘記目前密碼？": "Forgot current password?",
    "不用填目前密碼，直接設新的；存好後你其他的裝置都會登出。": "Set a new one without the current password; once saved, all your other devices will be signed out.",
    "我記得，改填目前密碼": "I remember it — enter current password",
    "這個模式只能改密碼": "Only the password can be changed here",
    "設新密碼": "Set new password",
    "忘了目前密碼：在這台按上面的「忘記目前密碼？」直接設新的。": "Forgot your current password? On this device, click \"Forgot current password?\" above and set a new one.",
    "完全登不進來時，要請有主機權限的人用救援指令（npm run admin-rescue）。": "If you can't sign in at all, ask someone with server access to run the rescue command (npm run admin-rescue).",
    "完全登不進來時，請管理員（{0}）在「管理員設定」按「重設登入」。": "If you can't sign in at all, ask an admin ({0}) to click \"Reset sign-in\" in \"Admin settings\".",
    "不用目前密碼，直接設新密碼？": "Set a new password without the current one?",
    "你其他所有裝置（包括配對、登入碼登入的）都會登出，要用新密碼重新登入；這台不會登出。": "All your other devices (including ones signed in by pairing or login code) will be signed out and need the new password; this device stays signed in.",
    "舊的登入碼會失效。": "Your old login code will stop working.",
    "這件事會記在安全通知裡。": "This will be recorded in your security notices.",
    "已設新密碼。建議存到密碼管理器。{0}": "New password set. We recommend storing it in a password manager. {0}",
    "另外 {0} 台裝置已登出。": "{0} other devices have been signed out.",
