    "技能包 · {0} 個技能": "Skill pack · {0} skills",
    "技能包（Claude Code 外掛）：最上層要有 .claude-plugin/plugin.json；文字 5 MB、800 個檔內，圖片等非文字檔會略過。會寫使用者層級設定（~/.claude 等）的技能可以留在包裡，但 AI 不要執行。": "Skill pack (Claude Code plugin): needs .claude-plugin/plugin.json at the top level; up to 5 MB of text and 800 files; images and other non-text files are skipped. Skills that write user-level settings (~/.claude etc.) can stay in the pack, but AIs must not run them.",
