    "這是 AI 的 Token，只能給 AI 透過 API 使用，不能登入網頁。請貼你本人的登入碼。": "This is an AI token: it's only for AIs to use through the API and can't sign in to the web. Paste your own login code.",
    "這是人類紀錄卡：AI 只能讀。整理完請另建一張卡，並可把這張標「已完成」同時帶 mergedInto（例如 MAIN-12），其他都不能改。": "This is a human record card: AIs can only read it. When you've sorted it out, create a separate card; you may mark this one Done with mergedInto (e.g. MAIN-12). Nothing else can be changed.",
    "這是你本人的登入碼，等同密碼：在其他裝置的登入頁選「用登入碼登入」貼上即可用同一身分登入（換裝置比較建議用「我的裝置」的 6 位數配對）。不要給 AI 用；AI 請到「我的 AI」建立專屬身分。覺得外流了就按「換一組登入碼」，舊的立刻失效，已登入的裝置不受影響。": "This is your personal login code and works like a password: on another device's login page, choose \"Log in with login code\" and paste it to sign in as you (for switching devices, the 6-digit pairing in \"My devices\" is recommended). Don't give it to an AI; create a dedicated identity for AIs in \"My AIs\". If you think it leaked, click \"Get a new login code\": the old one stops working immediately, and signed-in devices are not affected.",
    "這是決策卡 {0} 的說明；要決定請到": "This explains decision card {0}; to decide, go to",
    "這是系統自動建的管理員帳號。改好後請用新的帳號密碼登入其他裝置。": "This admin account was created automatically by the system. After changing it, use the new username and password to log in on other devices.",
    "這是空站，可以匯入備份。": "This site is empty, so you can import a backup.",
    "這是重設登入的連結：按「加入」後，這台裝置會以你原本的身分登入。": "This is a login reset link: after you click \"Join\", this device will log in as your existing account.",
    "這是接入用的機密{0}，不要貼群組（卡片、私訊也不行）：拿到的人就能冒用。請直接貼到你的 AI 對話；已經貼出去的話，到「我的 AI」{1}。": "This is a secret {0} for onboarding. Don't post it in the group (not in cards or DMs either): anyone who gets it can impersonate you. Paste it straight into your AI chat. If it's already been posted, go to \"My AIs\" and {1}.",
