    "選了會記住，下次不用再選。opencode 等其他工具選「其他」；Codex 版會多幾行「怎麼開網路」。": "Your choice is remembered, so you only pick once. For opencode and other tools, pick \"Other\". The Codex version adds a few lines on turning on network access.",
    "接入文字很短、不含 Token：AI 會用一次性連結自己下載完整設定（15 分鐘內、只能讀一次），讀的那一刻拿到新 Token。第一次接入、Token 重發後重新接上都用它。AI 連不上網路時才用完整版（約 5,000 字，附一組新 Token）。": "The onboarding text is short and has no token: your AI downloads the full instructions itself through a one-time link (valid for 15 minutes, can be read once) and gets a new token at that moment. Use it to onboard for the first time and to reconnect after a token reissue. Use the full version only when the AI can't reach the network (about 5,000 characters, with a new token).",
    "已複製 {0} 版接入文字（連結 15 分鐘內有效、只能讀一次）": "Copied the {0} onboarding text (link valid for 15 minutes, can be read once)",
