    "平台只存 Token 的雜湊，看不到原本的，所以完整接入設定會附": "Only a hash of the token is stored, so the original can't be shown. The full setup therefore includes",
    "一組新 Token": "a new token",
    "現在用的會立刻失效，要把這份新設定貼給它。": "'s current token stops working right away; paste this new setup to it.",
    "複製接入文字？": "Copy onboarding text?",
    "AI 讀這個連結時會拿到": "When the AI reads this link it gets",
    "（平台只存 Token 的雜湊，看不到原本的）：": "(only a hash of the token is stored, so the original can't be shown):",
    "現在用的會在那時失效。": "'s current token stops working at that moment.",
    "平台只存 Token 的雜湊，看不到原本的；要複製就重發一組：": "Only a hash of the token is stored, so the original can't be shown. To copy it, reissue a new one:",
    "已建立 AI": "AI created",
    "{0}新 Token 到期：": "{0} New token expires: ",
    "Token 只有現在看得到：平台只存雜湊，關掉這個視窗後要再複製就得重發。": "You can see this token only now: only a hash is stored. After closing this window, you'll need to reissue to copy it again.",
    "已建立 {0}。": "Created {0}.",
    "{0} 的舊 Token 已立即失效。": "{0}'s old token stopped working.",
    "產生新的": "New code",
    "這是你本人的登入碼，等同密碼：在其他裝置的登入頁選「用登入碼登入」貼上即可用同一身分登入（換裝置比較建議用「我的裝置」的 6 位數配對）。不要給 AI 用；AI 請到「我的 AI」建立專屬身分。平台只存登入碼的雜湊，看不到原本的：要用就產生一組新的，舊的立刻失效，已登入的裝置不受影響；覺得外流了也是再產生一組。": "This is your personal login code and works like a password: paste it under \"Sign in with login code\" on another device to sign in as you (pairing with a 6-digit code under \"My devices\" is recommended). Don't give it to AIs; create a dedicated identity for each AI under \"My AIs\". Only a hash of the code is stored, so the original can't be shown: generate a new one when you need it. The old one stops working right away; devices already signed in are not affected. If you think it leaked, generate a new one too.",
    "停用帳號": "Disable account",
    "立刻登出他所有裝置、作廢登入碼，他的 AI 的 Token 也全部失效；訊息、卡片都留著，之後可以恢復": "Signs them out of every device and voids their login code; their AIs' tokens stop working too. Messages and cards are kept, and you can restore them later",
    "停用…": "Disable…",
    "群組管理員": "Group admin",
    "把管理員交給他，你變一般成員": "Hand the admin role to them; you become a regular member",
    "交給他…": "Hand over…",
    "已停用的成員": "Disabled members",
    "登入和他的 AI 都不能用；恢復後他要重新登入，AI 要他重發 Token": "They can't sign in and their AIs can't connect. After restoring, they sign in again and reissue their AIs' tokens",
    "停用 {0}？": "Disable {0}?",
    "所有裝置立刻登出、登入碼作廢，他的 AI 的 Token 也全部失效。訊息、卡片、文件都留著；之後可以在「已停用的成員」恢復。": " will be signed out of every device right away, the login code voided, and all their AIs' tokens will stop working. Messages, cards and documents are kept; you can restore them under \"Disabled members\".",
    "已停用 {0}，{1} 隻 AI 的 Token 已失效": "Disabled {0}; {1} AI tokens stopped working",
    "已停用 {0}": "Disabled {0}",
    "已恢復 {0}：請他用帳號密碼重新登入": "Restored {0}: ask them to sign in again with their username and password",
    "把群組管理員交給 {0}？": "Hand the group admin role to {0}?",
    "交給他": "Hand over",
    "交出後": "After handing over,",
    "是群組管理員，你變一般成員：管理員設定都要請他處理。": " is the group admin and you become a regular member: Admin settings will be up to them.",
    "群組管理員已交給 {0}": "Group admin handed to {0}",
    "產生新的登入碼？": "Generate a new login code?",
    "產生": "Generate",
    "平台只存登入碼的雜湊，看不到原本的。產生新的之後，": "Only a hash of the login code is stored, so the original can't be shown. After generating a new one,",
    "舊的立刻失效": "the old one stops working right away",
    "（貼過舊登入碼、還沒登入的地方要改用新的）；已經登入的裝置不受影響。": " (anywhere you pasted the old code but haven't signed in yet needs the new one); devices already signed in are not affected.",
    "已產生新的登入碼，舊的已失效": "New login code generated; the old one no longer works",
    "預設管理員帳號是 admin。密碼請看安裝說明（README）或主機設定的 ADMIN_PASSWORD。其他人：": "The default administrator username is admin. For the password, see the README or the host's ADMIN_PASSWORD setting. Everyone else: ",
    "正在檢查登入服務…": "Checking sign-in availability…",
    "無法初始化預設管理員": "Could not initialize the default administrator",
    "無法初始化預設管理員。請主機管理員檢查資料庫連線、寫入權限與伺服器日誌，再按重試。": "Could not initialize the default administrator. Ask the host administrator to check the database connection, write permissions, and server logs, then retry.",
    "無法確認登入服務狀態。請確認伺服器已啟動且連線正常，再按重試。": "Could not check sign-in availability. Make sure the server is running and reachable, then retry.",
    "主人已停用": "Owner disabled",
    "平台不保存 Token 原文，所以完整接入設定會附": "The platform doesn't keep the original token, so the full setup includes",
    "（平台不保存 Token 原文）：": "(the platform doesn't keep the original token):",
    "平台不保存 Token 原文；要複製就重發一組：": "The platform doesn't keep the original token. To copy one, reissue it:",
    "Token 只有現在看得到：平台不保存原文，關掉這個視窗後要再複製就得重發。": "You can see this token only now: the platform doesn't keep the original. After closing this window, you'll need to reissue to copy it again.",
    "已設定（看不到原文，要用請產生新的）": "Set (the original can't be shown; generate a new one to use it)",
    "這是你本人的登入碼，等同密碼：在其他裝置的登入頁選「用登入碼登入」貼上即可用同一身分登入（換裝置比較建議用「我的裝置」的 6 位數配對）。不要給 AI 用；AI 請到「我的 AI」建立專屬身分。平台不保存登入碼原文：要用就產生一組新的，舊的立刻失效，已登入的裝置不受影響；覺得外流了也是再產生一組。": "This is your personal login code and works like a password: paste it under \"Sign in with login code\" on another device to sign in as you (pairing with a 6-digit code under \"My devices\" is recommended). Don't give it to AIs; create a dedicated identity for each AI under \"My AIs\". The platform doesn't keep the original code: generate a new one when you need it. The old one stops working right away; devices already signed in are not affected. If you think it leaked, generate a new one too.",
    "交出後你不能自己拿回來，要請": "After handing over, you can't take it back yourself; ask",
    "再交給你。": "to hand it back to you.",
    "平台不保存登入碼原文。產生新的之後，": "The platform doesn't keep the original login code. After generating a new one,",
    "平台不保存登入碼原文；要用請產生一組新的（POST /api/me/login-code，舊的會失效）。": "The platform doesn't keep the original login code. Generate a new one to use it (POST /api/me/login-code); the old one stops working.",
    "有 {0} 張你負責的卡還在待整理，還不用動手。": "You own {0} card(s) still in Triage; nothing to do yet.",
