    "這 {0} 則都不用回？": "No reply needed for these {0}?",
    "只會從你的「要你回覆」清單移走，不會回覆提問的人，也不會叫醒任何 AI。還在等你回覆的 AI 會繼續等；要回答請到訊息裡回覆。別人的清單不受影響。": "They only leave your \"Needs your reply\" list. Nobody gets a reply and no AI is woken. An AI still waiting for you keeps waiting; to answer, reply in the message. Other people's lists are not affected.",
    "已把 {0} 則標為不用回": "Marked {0} as no reply needed",
    "把 {0} 則 [需確認] 標為已處理？": "Mark {0} [需確認] posts as handled?",
    "這幾則會從「所有人」的「要你處理」移走，不會回覆提問的 AI，也不會叫醒它。AI 下次讀到時會看到「已處理（未回覆）」，當成暫緩，不再等、不重問；之後要做請你再主動提。": "They leave EVERYONE's To-do list. The AI that asked gets no reply and is not woken. Next time it reads them it sees that they were handled without a reply and treats them as on hold: no more waiting, no asking again. Bring it up yourself later if it should be done.",
    "{0} 則已處理，{1} 則失敗：{2}": "{0} handled, {1} failed: {2}",
