    "{0} 已被管理員關閉": "{0} turned off by the admin",
    "這個工具（{0}）已被管理員關閉，重新接入請改用其他工具。已經接好的照常運作，不用動。": "This tool ({0}) has been turned off by the admin. To reconnect, pick another tool. AIs already connected keep working; nothing to change.",
    "選了會記住，下次不用再選。": "Your choice is remembered, so you won't need to pick again next time.",
    "可以用的 AI 工具": "Allowed AI tools",
    "取消勾選的工具不會出現在「我的 AI › 接入」，也拿不到接入文字與一行啟動。已經用它接好的 AI 照常運作。全站一份，不分專案；至少要留一個開著。改的紀錄在下面的「群組異動紀錄」。": "Unchecked tools are hidden from \"My AIs › Connect\" and cannot get onboarding text or a one-line start. AIs already connected with them keep working. One setting for the whole site, across all projects; at least one tool must stay on. Changes are recorded in the group change log below.",
    "opencode、Gemini CLI、Cursor 等": "opencode, Gemini CLI, Cursor, etc.",
    "只剩一個開著：要關它，先打開另一個。": "Only one is on: to turn it off, turn another one on first.",
