    "{0}（含腳本，要核准才上架）": "{0} (include scripts; need approval before they're published)",
    "去看": "View",
    "邀請快到期 {0} 個": "Invites about to expire: {0}",
    "（重設登入）": " (login reset)",
    "延長或重發": "Extend or resend",
    "有效 {0}": "{0} active",
    "管理員設定的區塊": "Admin settings sections",
    "加入申請也會出現在左側「要你處理」；技能核准和邀請到期只在這裡。": "Join requests also appear in \"Your to-do\" on the left; skill approvals and expiring invites appear only here.",
    "目前沒有要管理員處理的事。加入申請、要核准的技能、快到期的邀請會出現在這裡。": "Nothing needs the admin right now. Join requests, skills awaiting approval and invites about to expire will show up here.",
    "交接管理員…": "Hand over admin…",
    "把群組管理員交給他，你變一般成員": "Make them the group admin; you become a regular member",
    "每個人的帳號": "Everyone's account",
    "跨專案角色開了會自動在所有專案{0}，切換後，下方會出現「檢查並儲存」，跟其他變更一起存；重設登入、停用、交接管理員會立即執行（會先確認）": "With a cross-project role, the member is in every project automatically {0}. After you switch it, \"Review and save\" appears below and it is saved with your other changes. Reset login, disable and hand over admin take effect immediately (you'll be asked to confirm first).",
    "帳號動作": "Account actions",
    "重設登入：登出他所有裝置、作廢舊登入碼、清掉帳號密碼，產生新邀請連結讓他重新登入（他的 AI 不受影響），連結會列在「邀請」。停用：他和他的 AI 都登不進來，訊息、卡片留著，可以在下面恢復。": "Reset login signs them out on every device, revokes old login codes, clears their username and password, and creates a new invite link so they can sign in again (their AIs aren't affected). The link is listed under \"Invites\". Disable: neither they nor their AIs can sign in; messages and cards stay, and you can restore them below.",
    "救援指令（管理員自己登不進來時）": "Rescue command (when the admin can't sign in)",
    "其他人登不進來，用上面的「重設登入」。管理員自己完全登不進來（裝置都登出了、又忘了密碼），請有主機權限的人在程式資料夾執行：": "If someone else can't sign in, use \"Reset login\" above. If the admin can't sign in at all (signed out everywhere and forgot the password), ask someone with server access to run this in the app folder:",
    "APP_URL=https://你的網址 npm run admin-rescue": "APP_URL=https://your-site npm run admin-rescue",
    "會產生一次性的救援登入連結（15 分鐘內、只能用一次），只救管理員。本機或 Docker 版（node server.js）改用": "It creates a one-time rescue login link (valid 15 minutes, single use) for the admin only. For the local or Docker version (node server.js), use",
    "，有設": "; if",
    "就照同一組設定連 Postgres。": "is set, it connects to Postgres with the same settings.",
