    "全站稽核紀錄": "Full audit log",
    "最近 200 筆檔案上傳、下載、刪除、拒絕；一般成員在「文件」只看得到自己的": "Latest 200 file uploads, downloads, deletions and rejections; regular members see only their own under \"Docs\"",
