    "），wrangler.toml 綁定": "), bind",
    "後重新部署。本機與 Docker 版存在 data 資料夾，不用開通。": "in wrangler.toml and redeploy. The local and Docker versions store files in the data folder, so nothing to enable.",
    "開通前不能上傳訊息附件": "Message attachments can't be uploaded until it's enabled",
    "{0} 分鐘": "{0} min",
    "Enter 送出 · Shift+Enter 換行 · 輸入 @ 提及成員 · 上傳的文件 {0}後自動刪除": "Enter to send · Shift+Enter for new line · type @ to mention · uploaded files are deleted after {0}",
    "Enter 送出 · Shift+Enter 換行 · 輸入 @ 提及成員 · 上傳的文件過了保存時間自動刪除": "Enter to send · Shift+Enter for new line · type @ to mention · uploaded files are deleted when their retention time ends",
    "上傳 {0}後自動刪除": "Deleted automatically {0} after upload",
    "保存時間由管理員設定，目前上傳 {0}後自動刪除；設定改了只影響之後上傳的檔，已上傳的照各自顯示的時間刪除。": "The admin sets how long attachments are kept. Files uploaded now are deleted automatically after {0}. A change only applies to later uploads; files already uploaded are deleted at the time shown for each.",
    "頭像會裁成正方形、縮成 256 × 256 px 後儲存，不會像訊息附件在 {0}後刪除。請勿使用含客戶個資的圖片。": "The avatar is cropped to a square and resized to 256 × 256 px before saving; unlike message attachments, it is not deleted after {0}. Do not use images containing customers' personal data.",
    "上傳到平台後，所有群組成員都能下載，{0}後自動刪除。每張截圖都請先確認沒有客戶資料。": "Once uploaded, every group member can download these. They are deleted automatically after {0}. Make sure no screenshot contains customer data.",
    "上傳到平台後，所有群組成員都能下載，{0}後自動刪除。{1}": "Once uploaded, all group members can download it. It's deleted automatically after {0}.{1}",
    "已用 {0} / {1} · 上傳 {2}後自動刪除": "Used {0} / {1} · deleted automatically {2} after upload",
    "訊息附件保存時間": "Attachment retention",
    "只有訊息附件（在訊息裡上傳的文件、截圖）會在這段時間後自動刪除。專案文件和知識庫都不會自動刪除；知識庫裡的文件就是專案文件，只存一份。改了只影響之後上傳的檔；已經上傳的照上傳當時的設定到期，不會提早或延後刪除。存好立即生效，不用重新啟動或部署。": "Only message attachments (files and screenshots uploaded in messages) are deleted after this time. Project docs and the knowledge base are never deleted automatically; knowledge base files are project docs, stored once. A change only applies to later uploads; files already uploaded expire under the setting in effect when they were uploaded, never earlier or later. Takes effect as soon as you save, no restart or redeploy needed.",
    "目前用這裡的設定。主機的 {0} 只決定還沒改過時的初始值，改過之後就以這裡為準。": "This setting is in use. The server's {0} only sets the starting value until someone changes it here; after that, this setting wins.",
    "目前用主機 {0} 的值（{1}）。在這裡改過之後就以這裡為準，{2} 不再影響。": "Currently using the server's {0} value ({1}). Once you change it here, this setting wins and {2} no longer applies.",
    "目前是預設的 24 小時（主機沒設 {0}）。主機設了 {1} 會改用它當初始值；在這裡改過之後就以這裡為準。": "Currently the default of 24 hours (the server has no {0}). If the server sets {1}, that becomes the starting value; once you change it here, this setting wins.",
    "{0} 把保存時間從 {1} 改成 {2}": "{0} changed retention from {1} to {2}",
    "已儲存：之後上傳的訊息附件保存 {0}；已上傳的照原本的到期時間": "Saved: attachments uploaded from now on are kept for {0}; files already uploaded keep their original expiry",
    "hours 只能是 {0}（小時）": "hours must be one of {0} (hours)",
