    "原文是逐字比對：搜「年假」找不到寫「特別休假」的原文，但知識頁有寫常見問法，所以會出現在上面那區。": "Original docs are matched word for word: searching \"annual leave\" won't find text that says \"paid time off\". Knowledge pages list common phrasings, so they show up in the section above.",
    "找不到「{0}」。原文是逐字比對，試試換個說法（例如「年假」改搜「特別休假」），或少打幾個詞。": "Nothing found for \"{0}\". Original docs are matched word for word, so try other wording (e.g. \"paid time off\" instead of \"annual leave\") or fewer words.",
